import{service,api,escape,date}from'./service.js';import{icon}from'./icons.js';import{auth}from'./auth.js';import{bindUploader}from'./uploader.js';import{openShareManager}from'./sharelinks.js';export const types=['Mariage','Portrait','Anniversaire','Bébé / Famille','Événement','Baptême','Remise de diplômes','Conférence','Événement d’entreprise','Concert','Festival','Séance photo','Séance famille','Événement scolaire','Autre'];
let uploadEventId=null;const mb=b=>(b/1024/1024).toFixed(1)+' Mo';
const isOwner=()=>auth.session()?.role==='owner';
const initials=n=>String(n||'').split(/\s+/).filter(Boolean).map(w=>w[0]).join('').slice(0,2).toUpperCase();
const roleLabel={owner:'Propriétaire',admin:'Admin',client:'Client'};
const ago=iso=>{if(!iso)return 'Jamais connecté';const d=(Date.now()-new Date(iso))/864e5;return d<1?'Connecté aujourd’hui':d<2?'Connecté hier':`Connecté il y a ${Math.floor(d)} j`};
// Blocs réutilisés : en-tête de page, personne (avatar + nom), badge de statut.
const head=(title,actions='')=>`<header class="page-head"><h1>${title}</h1>${actions?`<div class="page-actions">${actions}</div>`:''}</header>`;
const accountOf=a=>(service.data.accounts||[]).find(x=>(a.id&&x.id===a.id)||(a.email&&x.email===a.email));
const person=(a,sub=a.email)=>`<div class="person">${(a.avatar?a:accountOf(a))?.avatar?`<img class="avatar" src="${escape((a.avatar?a:accountOf(a)).avatar)}" alt="">`:`<span class="avatar">${escape(initials(a.name))}</span>`}<div><strong>${escape(a.name)}</strong><span>${escape(sub)}</span></div></div>`;
const pill=(label,kind='')=>`<span class="badge ${kind}">${label}</span>`;
const eventStatus=e=>e.archived?pill('Archivé','is-muted'):e.expiresAt&&e.expiresAt<new Date().toISOString().slice(0,10)?pill('Expirée','is-muted'):e.published?pill('Publié','is-live'):pill('Brouillon','is-draft');
const ibtn=(label,attr,ico,cls='',badge='')=>`<button type="button" class="btn sm icon-btn ${cls}" ${attr} title="${label}" aria-label="${label}" data-tip="${label}">${icon(ico)}${badge?`<b class="icon-badge">${badge}</b>`:''}</button>`;
const btn=(label,attr,ico='',cls='')=>`<button class="btn sm ${cls}" ${attr}>${ico?icon(ico):''}${label}</button>`;
const ownerOf=e=>service.data.accounts.find(a=>a.id===e.clientId);
export function adminContent(page){const d=service.data;const me=auth.session();
if(page==='Overview')return `${head(`Bonjour ${escape(me.name.split(' ')[0])}`)}${d.mail.configured?'':`<div class="callout">${icon('mail')}<span>E-mails automatiques désactivés : ajoutez votre clé Resend dans <code>server/.env</code>.</span><button class="text-link" data-nav="Emails">Voir</button></div>`}<section class="quick-tools"><button id="new-client-quick"><span class="tool-icon">${icon('users')}</span><span><strong>Nouveau client</strong></span>${icon('arrow')}</button><button id="new-event"><span class="tool-icon">${icon('events')}</span><span><strong>Nouvel événement</strong></span>${icon('arrow')}</button><button data-nav="Photos"><span class="tool-icon">${icon('upload')}</span><span><strong>Importer des photos</strong></span>${icon('arrow')}</button>${d.selections?.length?`<button data-nav="Selections"><span class="tool-icon">${icon('check')}</span><span><strong>Sélections reçues</strong><small>${d.selections.length} envoyée${d.selections.length>1?'s':''}</small></span>${icon('arrow')}</button>`:''}</section><div class="stats">${[['Clients',d.clients.length,'users'],['Galeries',d.events.length,'events'],['Photos',d.photos.length,'photos'],['Stockage',mb(d.stats.storageBytes),'albums']].map(([l,n,i])=>`<div class="stat">${icon(i)}<p>${l}</p><strong>${n}</strong></div>`).join('')}</div><div class="section-heading"><h2>Galeries récentes</h2><button class="text-link" data-nav="Events">Tout voir</button></div>${eventTable(d.events.slice(0,5))}<div class="section-heading"><h2>Activité des clients</h2></div><div class="settings list">${d.activity.length?d.activity.map(a=>`<div class="row between">${person(a,ago(a.lastLoginAt))}<p class="small">${a.favorites} favoris · ${a.downloads} photos téléchargées</p></div>`).join(''):'<p>Aucun client pour le moment.</p>'}</div>`;
if(page==='Clients')return `${head('Clients',btn('Nouveau client','id="new-client"','plus','primary'))}${d.clients.length?`<div class="table-wrap clients-wrap"><table class="clients-table"><thead><tr><th>Client</th><th>Galeries</th><th>Statut</th><th></th></tr></thead><tbody>${d.clients.map(c=>`<tr><td>${person(c)}</td><td>${d.events.filter(e=>e.clientId===c.id).length}</td><td>${c.active?pill('Actif','is-live'):pill('En pause','is-muted')}<p class="small">${ago(c.lastLoginAt)}</p></td><td class="actions">${ibtn('Ajouter des photos',`data-add-photos="${c.id}"`,'upload')}${ibtn(c.active?'Mettre en pause':'Réactiver',`data-toggle-client="${c.id}"`,c.active?'pause':'play',c.active?'':'is-off')}${ibtn('Gérer le client',`data-manage-client="${c.id}"`,'more')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('users')}<h2>Aucun client</h2></div>`}`;
if(page==='Team')return `${head('Équipe',isOwner()?`${btn('Nouveau propriétaire','id="new-owner"','shield')}${btn('Nommer un client admin','id="promote-client"','shield')}${btn('Nouvel admin','id="new-admin"','plus','primary')}`:'')}<div class="team-grid">${d.team.map(a=>`<article class="team-card${a.active?'':' is-off'}">${person(a)}<div class="row">${pill(roleLabel[a.role],a.role==='owner'?'is-live':'')}${a.active?'':pill('Désactivé','is-muted')}${a.id===me.id?pill('Vous','is-draft'):''}</div><p class="small">${ago(a.lastLoginAt)} · ${d.events.filter(e=>e.clientId===a.id).length} galerie(s)</p>${a.accessCode?`<p class="small">Code d’accès : <b style="letter-spacing:.15em">${escape(a.accessCode)}</b></p>`:''}${isOwner()&&a.role==='owner'&&a.id!==me.id?`<div class="team-actions">${ibtn('Retirer propriétaire',`data-remove-owner="${a.id}"`,'shieldOff','danger')}</div>`:''}${isOwner()&&a.role==='admin'?`<div class="team-actions">${ibtn('Nommer propriétaire',`data-make-owner="${a.id}"`,'shield')}${ibtn('Retirer admin',`data-demote="${a.id}"`,'shieldOff','danger')}${ibtn(a.active?'Désactiver':'Activer',`data-toggle-admin="${a.id}"`,'power',a.active?'':'is-off')}${ibtn('Mot de passe',`data-reset-admin="${a.id}"`,'key')}${ibtn('Réinitialiser le mot de passe du studio',`data-reset-studio="${a.id}"`,'shield')}${ibtn('Message',`data-message="${a.id}"`,'mail')}</div>`:''}</article>`).join('')}</div>`;
if(page==='Emails')return `${head('E-mails')}<div class="callout${d.mail.configured?' is-ok':''}">${icon(d.mail.configured?'check':'mail')}<span>${d.mail.configured?`Envoi actif depuis <strong>${escape(d.mail.from)}</strong>`:'Envoi désactivé : ajoutez <code>RESEND_API_KEY</code> et <code>MAIL_FROM</code> dans <code>server/.env</code>, puis redémarrez le serveur.'}</span></div><section class="settings email-test"><h2>Espace test</h2><div class="test-row"><label>Modèle<select id="test-kind">${Object.entries(kindLabel).filter(([k])=>k!=='test').map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label><label>Envoyer à<input id="test-to" type="email" value="${escape(me.email)}"></label><button class="btn primary" id="send-test">${icon('send')} Envoyer le test</button></div><div class="email-frame"><p class="small" id="test-subject"></p><iframe id="test-preview" title="Aperçu de l’e-mail" sandbox></iframe></div></section><div class="section-heading"><h2>Historique</h2></div><div id="email-log"><div class="empty">${icon('mail')}<h2>Chargement…</h2></div></div>`;
if(page==='Announcements')return `${head('Notifications',btn('Nouvelle notification','id="new-announcement"','plus','primary'))}<div class="callout${d.mail.configured?' is-ok':''}">${icon('bell')}<span>Votre message apparaît dans la cloche de vos clients${d.mail.configured?' et leur est aussi envoyé par e-mail, tout de suite ou à l’heure choisie.':'. E-mails désactivés : ajoutez <code>RESEND_API_KEY</code> et <code>MAIL_FROM</code> dans <code>server/.env</code>.'}</span></div><div id="announcement-list"><div class="empty">${icon('bell')}<h2>Chargement…</h2></div></div>`;
if(page==='Selections')return `${head('Sélections')}<div class="lib-filters"><div class="lib-albums" role="group" aria-label="Filtrer les sélections">${[['all','Toutes'],['sent','Envoyées'],['open','En cours']].map(([k,l])=>`<button type="button" class="chip${selFilter===k?' active':''}" data-sel-filter="${k}">${l} <small data-sel-count="${k}"></small></button>`).join('')}</div></div><div id="sel-list"><div class="empty">${icon('check')}<h2>Chargement…</h2></div></div>`;
if(page==='Comments')return `${head('Commentaires')}<div class="filterbar comment-filters" id="comment-filters" role="group" aria-label="Filtrer les commentaires">${[['all','Tous'],['client','Clients'],['family','Famille'],['staff','Studio']].map(([k,l])=>`<button class="chip${commentFilter===k?' active':''}" data-cfilter="${k}">${l} <small data-ccount="${k}"></small></button>`).join('')}</div><div id="comment-list"><div class="empty">${icon('chat')}<h2>Chargement…</h2></div></div>`;
if(page==='Events')return `${head('Événements',btn('Nouvel événement','id="new-event"','plus','primary'))}${eventTable(d.events)}`;
if(page==='Albums'){const ev=d.events.find(e=>e.id===lib.eventId);if(!ev)lib.eventId='';const inEvent=d.photos.filter(p=>!lib.eventId||p.eventId===lib.eventId);const albums=[...new Set(inEvent.map(p=>p.album))];if(!albums.includes(lib.album))lib.album='';const list=libList();for(const id of[...lib.selected])if(!list.some(p=>p.id===id))lib.selected.delete(id);
return `${head('Photos',ev?btn('Ajouter des photos',`data-upload-to="${ev.id}"`,'upload','primary'):btn('Importer','data-nav="Photos"','upload','primary'))}<div class="lib-filters"><label>Galerie<select id="lib-event"><option value="">Toutes les galeries (${d.photos.length} photos)</option>${d.events.map(e=>`<option value="${e.id}" ${e.id===lib.eventId?'selected':''}>${escape(e.name)} — ${service.photos(e.id).length} photo${service.photos(e.id).length>1?'s':''}</option>`).join('')}</select></label>${albums.length>1?`<div class="lib-albums" role="group" aria-label="Albums"><button type="button" class="chip${lib.album?'':' active'}" data-lib-album="">Tous les albums</button>${albums.map(a=>`<button type="button" class="chip${a===lib.album?' active':''}" data-lib-album="${escape(a)}">${escape(a)} <small>${inEvent.filter(p=>p.album===a).length}</small></button>`).join('')}</div>`:''}</div>${list.length?`<div class="lib-bar${lib.selected.size?' has-selection':''}" id="lib-bar">${libBar(list,ev)}</div><div class="lib-grid" id="lib-grid">${list.map(libCard).join('')}</div>`:`<div class="empty">${icon('photos')}<h2>${ev?'Aucune photo dans cette galerie':'Aucune photo'}</h2>${ev?`<button class="btn primary" data-upload-to="${ev.id}" style="margin-top:16px">${icon('upload')} Ajouter des photos</button>`:''}</div>`}`}
if(page==='Photos')return `${head('Importer des photos')}${d.events.length?`<div style="max-width:450px"><label>Galerie<select id="upload-event">${d.events.map(e=>`<option value="${e.id}" ${e.id===uploadEventId?'selected':''}>${escape(e.name)} — ${escape(ownerOf(e)?.name||'')}</option>`).join('')}</select></label></div><div id="drop" class="dropzone">${icon('upload')}<h2>Déposez vos photos ici</h2><button id="browse" class="btn primary" style="margin-top:20px">Parcourir</button><p id="upload-hint" class="small" style="margin-top:14px"></p><input id="files" type="file" multiple hidden></div><div id="upload-list"></div>`:`<div class="empty">${icon('events')}<h2>Créez d’abord un événement.</h2><button class="btn primary" id="new-event" style="margin-top:16px">+ Nouvel événement</button></div>`}`;
if(page==='Settings')return `${head('Autorisations')}<div class="settings">${Object.entries(d.permissions).map(([key,value])=>`<label>${({individual:'Télécharger une photo',selection:'Télécharger une sélection',event:'Télécharger tout l’événement',favorites:'Favoris',comments:'Commentaires sous les photos',signup:'Création de compte depuis la page de connexion',sharing:'Partage famille (lien + mot de passe)',share_download:'La famille peut télécharger les photos d’un lien de partage'})[key]}<input class="switch" type="checkbox" data-permission="${key}" ${value?'checked':''}></label>`).join('')}</div>`;
if(page==='Storage')return `${head('Stockage')}<div class="stats"><div class="stat">${icon('albums')}<p>Espace utilisé</p><strong>${mb(d.stats.storageBytes)}</strong></div><div class="stat">${icon('photos')}<p>Photos</p><strong>${d.photos.length}</strong></div></div>${isOwner()?`<section class="settings storage-clean"><h2>Nettoyer l’espace</h2><p class="small">Cherche les fichiers qui ne servent plus à aucune photo, galerie ou compte (restes de suppressions interrompues, anciennes miniatures de visages). Rien n’est effacé avant votre confirmation, et les fichiers de moins de 24 h sont toujours gardés.</p><div class="row"><button class="btn" id="clean-scan">${icon('search')} Analyser</button><button class="btn primary" id="clean-run" hidden>${icon('trash')} Libérer l’espace</button></div><p class="small" id="clean-result" role="status"></p></section>`:''}`;return ''}
// ----- Page « Sélections » : les choix des clients (mode sélection), toutes galeries confondues -----
let selFilter='all',selCache=null;
/** [3,4,5,7] -> « 3-5, 7 » (le client peut retaper ce format). */
const compactNums=nums=>{const out=[];for(let i=0;i<nums.length;i++){let j=i;while(j+1<nums.length&&nums[j+1]===nums[j]+1)j++;out.push(j>i?`${nums[i]}-${nums[j]}`:`${nums[i]}`);i=j}return out.join(', ')};
const selMatches=s=>selFilter==='all'||(selFilter==='sent'?!!s.submittedAt:!s.submittedAt);
function selectionCard(s){const e=service.data.events.find(x=>x.id===s.eventId);const nums=s.photos.map(p=>p.number);const n=nums.length;const lim=e?.selectionLimit;
const status=s.submittedAt?(s.changedSince?pill('Modifiée après l’envoi','is-draft'):pill('Envoyée','is-live')):pill('En cours','is-muted');
return `<article class="sel-card${s.submittedAt?'':' is-open'}"><header class="sel-head">${person({name:s.name,avatar:s.avatar,email:s.email},e?.name||'Galerie supprimée')}<div class="sel-status">${status}<span class="small">${s.submittedAt?`le ${when(s.submittedAt)}`:s.lastPickAt?`dernier choix le ${when(s.lastPickAt)}`:''}</span></div></header><div class="sel-count"><strong>${n}</strong> photo${n>1?'s':''} choisie${n>1?'s':''}${lim?`<span class="small"> sur ${lim} maximum</span>`:''}</div>${n?`<p class="pick-list">N° ${escape(compactNums(nums))}</p>`:'<p class="small">Aucune photo choisie.</p>'}${s.note?`<blockquote>${escape(s.note).replace(/\r?\n/g,'<br>')}</blockquote>`:''}${n?`<div class="sel-thumbs" hidden>${s.photos.map(p=>`<figure><img src="${escape(p.thumb)}" alt="" loading="lazy"><figcaption>N° ${p.number}</figcaption></figure>`).join('')}</div><div class="sel-actions">${btn('Voir les photos','data-sel-toggle','eye')}${btn('Copier les numéros',`data-copy="${escape(nums.join(', '))}"`,'copy')}${btn('Copier les noms de fichiers',`data-copy="${escape(s.photos.map(p=>p.filename).join(', '))}" title="Pour retrouver les photos dans Lightroom ou l’explorateur"`,'copy')}</div>`:''}</article>`}
// ----- Page « Photos » : sélection (une, plusieurs, toutes), album, suppression -----
const lib={eventId:'',album:'',selected:new Set(),last:null};
const libList=()=>service.data.photos.filter(p=>(!lib.eventId||p.eventId===lib.eventId)&&(!lib.album||p.album===lib.album));
const plural=(n,one,many)=>`${n} ${n>1?many:one}`;
function libBar(list,ev){const n=lib.selected.size;const all=n>0&&n===list.length;return `<label class="lib-all"><input type="checkbox" id="lib-all" ${all?'checked':''}><span>${n?`<b>${n}</b> sélectionnée${n>1?'s':''} sur ${list.length}`:`Tout sélectionner <small>(${list.length})</small>`}</span></label><div class="lib-actions">${n?`${btn('Désélectionner','id="lib-clear"','close')}${btn('Mettre dans un album','id="lib-move"','albums')}${btn(`Supprimer ${plural(n,'photo','photos')}`,'id="lib-delete"','trash','danger')}`:`<span class="small lib-hint">Touchez les photos à sélectionner · Maj + clic pour une série</span>${ev?btn('Vider la galerie','id="lib-delete-all"','trash','danger ghost'):''}`}</div>`}
function libCard(p){const d=service.data;const sel=lib.selected.has(p.id);const e=d.events.find(e=>e.id===p.eventId);const cover=!!e?.cover&&(e.cover.includes(`v=${p.id}`)||e.cover.endsWith(`/preview/${p.id}`));return `<article class="lib-card${sel?' is-selected':''}" data-lib-photo="${p.id}"><button type="button" class="lib-pick" aria-pressed="${sel}" aria-label="Sélectionner ${escape(p.filename)}"><img src="${escape(p.thumb||p.preview)}" alt="" loading="lazy" decoding="async"><span class="lib-check">${icon('check')}</span>${p.number?`<span class="lib-num">N° ${p.number}</span>`:''}${cover?`<span class="lib-cover">${icon('star')} Couverture</span>`:''}</button><div class="lib-tools">${ibtn('Monter',`data-up-photo="${p.id}"`,'up')}${ibtn('Définir comme couverture',`data-cover-photo="${p.id}"`,'star')}${ibtn('Supprimer',`data-remove-photo="${p.id}"`,'trash','danger')}</div><div class="lib-meta"><strong title="${escape(p.filename)}">${escape(p.filename)}</strong><span>${escape(lib.eventId?p.album:`${e?.name||''} · ${p.album}`)}</span></div></article>`}
function eventTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Galerie</th><th>Pour</th><th>Date</th><th>Photos</th><th>Statut</th><th></th></tr></thead><tbody>${list.map(e=>{const o=ownerOf(e);return `<tr><td><div class="person">${e.cover?`<img class="thumb" src="${escape(e.cover)}" alt="" loading="lazy">`:`<span class="thumb">${icon('photos')}</span>`}<div><strong>${escape(e.name)}</strong><span>${escape(e.type)}</span></div></div></td><td>${o?`<span class="owner-cell">${o.avatar?`<img class="avatar xs" src="${escape(o.avatar)}" alt="">`:`<span class="avatar xs">${escape(initials(o.name))}</span>`}${escape(o.name)}</span>`:'—'}${o&&o.role!=='client'?` ${pill(roleLabel[o.role],'is-draft')}`:''}</td><td>${date(e.date)}</td><td>${service.photos(e.id).length}</td><td>${eventStatus(e)}${e.selectionMode?` ${pill('Sélection','is-draft')}`:''}</td><td class="actions">${e.selectionMode?ibtn('Sélection du client',`data-view-selection="${e.id}"`,'check','',service.data.selections.filter(x=>x.eventId===e.id).length||''):''}${e.published&&!e.archived?ibtn('Prévenir le client',`data-notify="${e.id}"`,'send'):''}${e.published&&!e.archived?ibtn('Partage famille (lien + mot de passe)',`data-share-event="${e.id}"`,'link'):''}${ibtn('Photos de la galerie',`data-lib-event="${e.id}"`,'photos')}${ibtn('Gérer',`data-manage-event="${e.id}"`,'edit')}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">${icon('events')}<h2>Aucun événement</h2></div>`}
const kindLabel={test:'Test',selection:'Sélection reçue',welcome:'Bienvenue',gallery_ready:'Photos prêtes',expiry:'Galerie bientôt fermée',password_reset:'Mot de passe',admin_invite:'Invitation équipe',message:'Message',announcement:'Notification'};
const when=iso=>new Date(iso).toLocaleString('fr-FR',{day:'numeric',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'});
const emailsDone=a=>a.emailsSent+a.emailsFailed>=a.recipients;
const isLater=a=>a.sendAt>new Date().toISOString();
function noticeMail(a){if(!a.sendEmail)return pill('Cloche seulement','is-muted');if(isLater(a))return pill('E-mail programmé','is-draft');if(!emailsDone(a))return pill(`E-mails : ${a.emailsSent} / ${a.recipients}…`,'is-draft');return a.emailsFailed?pill(`${a.emailsSent} e-mail(s) envoyé(s) · ${a.emailsFailed} non envoyé(s)`,'is-muted'):pill(`${a.emailsSent} e-mail${a.emailsSent>1?'s':''} envoyé${a.emailsSent>1?'s':''}`,'is-live')}
function announcementList(list){return list.length?`<div class="notice-list">${list.map(a=>{const later=isLater(a);return `<article class="notice-row${later?' is-later':''}"><span class="notice-icon">${icon(later?'clock':'bell')}</span><div class="notice-main"><div class="notice-meta"><strong>${escape(a.title)}</strong>${noticeMail(a)}</div><p>${escape(a.body).replace(/\r?\n/g,'<br>')}</p><p class="small">${later?`Programmée pour le ${when(a.sendAt)}`:`Publiée le ${when(a.sendAt)}`} · ${a.audience==='all'?`Tous les clients (${a.recipients})`:escape(a.names||`${a.recipients} client(s)`)}${a.eventName?` · Galerie : ${escape(a.eventName)}`:''}${isOwner()&&a.author&&a.author!==auth.session().name?` · par ${escape(a.author)}`:''}</p></div><div class="actions">${ibtn(later?'Annuler l’envoi':'Supprimer',`data-del-announcement="${a.id}"`,'trash','danger')}</div></article>`}).join('')}</div>`:`<div class="empty">${icon('bell')}<h2>Aucune notification</h2><p class="small">Annonce, promotion, rappel… vos clients la verront dans leur cloche.</p></div>`}
function emailTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>Destinataire</th><th>Type</th><th>Objet</th><th>Statut</th><th>Date</th></tr></thead><tbody>${list.map(m=>`<tr><td>${person({name:m.name||m.to,email:m.to})}</td><td>${kindLabel[m.kind]||escape(m.kind)}</td><td>${escape(m.subject)}</td><td>${m.status==='sent'?pill('Envoyé','is-live'):m.status==='failed'?pill('Échec','is-muted'):pill('Non envoyé','is-draft')}${m.error?`<p class="small" title="${escape(m.error)}">${escape(m.error.slice(0,60))}</p>`:''}</td><td>${new Date(m.date).toLocaleString('fr-FR')}${m.sender?`<p class="small">par ${escape(m.sender)}</p>`:''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('mail')}<h2>Aucun e-mail envoyé</h2></div>`}
let commentFilter='all',commentCache=null;
/** Filtre de la page Commentaires : client, famille (lien de partage) ou studio. */
const commentKind=(c,k)=>k==='all'||(k==='family'?!!c.author.family:k==='staff'?!!c.author.staff:!c.author.family&&!c.author.staff);
const avatarOf=a=>a.avatar?`<img class="avatar" src="${escape(a.avatar)}" alt="">`:`<span class="avatar">${escape(initials(a.name))}</span>`;
function commentList(list){return list.length?`<div class="comment-list">${list.map(c=>`<article class="comment-row${c.author.staff?' is-staff':''}"><img class="thumb lg" src="${escape(c.photo.preview)}" alt="" loading="lazy"><div class="comment-main"><div class="comment-meta">${avatarOf(c.author)}<strong>${escape(c.author.name)}</strong>${c.author.staff?pill('Studio','is-live'):''}${c.author.family?pill(c.author.via?`Famille · ${escape(c.author.via)}`:'Famille','is-draft'):''}<span>${escape(c.event.name)} · ${escape(c.photo.filename)}</span><time>${new Date(c.date).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time></div><p>${escape(c.body).replace(/\n/g,'<br>')}</p><div class="row">${ibtn('Répondre',`data-reply="${c.photo.id}" data-reply-name="${escape(c.photo.filename)}"`,'chat')}${ibtn('Supprimer',`data-del-comment="${c.id}"`,'trash','danger')}</div></div></article>`).join('')}</div>`:`<div class="empty">${icon('chat')}<h2>Aucun commentaire</h2></div>`}
// Formulaire -> FormData (fichiers vides ignorés) pour les routes multipart.
const toForm=values=>{const f=new FormData();for(const[k,v]of Object.entries(values))if(!(v instanceof File)||v.size)f.append(k,v);return f};
const sendBox=(label,checked=true)=>`<label><span>${label}</span><input type="checkbox" name="sendEmail" ${checked?'checked':''}></label>`;
/** Message de confirmation + résultat de l'e-mail éventuel renvoyé par le serveur. */
export const withEmail=(msg,email)=>!email?msg:email.status==='sent'?`${msg} E-mail envoyé.`:email.status==='skipped'?`${msg} (e-mail non envoyé : Resend non configuré)`:`${msg} Échec de l’e-mail : ${email.error}`;
export function bindAdmin(page,render,toast,modal,navigate,refresh){const d=service.data;
// Clic -> appel API ; toute erreur du serveur s'affiche dans un toast.
const act=fn=>async(...a)=>{try{await fn(...a)}catch(e){toast(e.message)}};
const byId=id=>d.accounts.find(a=>a.id===id);
// ----- Stockage : nettoyer l'espace inutilisé (propriétaire) -----
if(page==='Storage'){const scan=document.getElementById('clean-scan'),run=document.getElementById('clean-run'),out=document.getElementById('clean-result');if(scan){const names={originals:'originaux',previews:'aperçus',thumbs:'miniatures',covers:'couvertures',avatars:'photos de profil',music:'musiques',watermarks:'filigranes',faces:'miniatures de visages',tmp:'fichiers temporaires'};const detail=r=>Object.entries(r.byFolder).map(([k,v])=>`${v.count} ${names[k]||k}`).join(', ');
scan.onclick=act(async()=>{scan.disabled=true;out.textContent='Analyse en cours…';try{const r=await api('/api/admin/storage/orphans');if(!r.count){out.textContent='Rien à nettoyer : tout l’espace utilisé sert à quelque chose.';run.hidden=true}else{out.textContent=`${r.count} fichier(s) inutiles, soit ${mb(r.bytes)} à libérer (${detail(r)}).`;run.hidden=false}}finally{scan.disabled=false}});
run.onclick=act(async()=>{if(!confirm('Supprimer définitivement ces fichiers inutilisés ? Aucune photo en cours d’utilisation n’est touchée.'))return;run.disabled=true;out.textContent='Nettoyage en cours…';try{const r=await api('/api/admin/storage/cleanup',{method:'POST'});out.textContent=`${r.count} fichier(s) supprimé(s) : ${mb(r.bytes)} libérés.`;run.hidden=true;toast('Espace libéré.')}finally{run.disabled=false}})}}
if(page==='Selections'){const host=document.getElementById('sel-list');
const draw=()=>{if(!host.isConnected)return;const all=selCache||[];for(const k of['all','sent','open']){const c=document.querySelector(`[data-sel-count="${k}"]`);const prev=selFilter;selFilter=k;if(c)c.textContent=all.filter(selMatches).length;selFilter=prev}
const list=all.filter(selMatches);host.innerHTML=list.length?`<div class="sel-grid">${list.map(selectionCard).join('')}</div>`:`<div class="empty">${icon('check')}<h2>${all.length?'Rien dans cette catégorie':'Aucune sélection pour le moment'}</h2><p class="small">${all.length?'Changez de filtre pour voir les autres sélections.':'Activez le « Mode sélection » sur une galerie (Événements → Gérer) : votre client choisira ses photos, et sa sélection arrivera ici.'}</p></div>`;
host.querySelectorAll('[data-sel-toggle]').forEach(b=>b.onclick=()=>{const t=b.closest('.sel-card').querySelector('.sel-thumbs');t.hidden=!t.hidden;b.lastChild.textContent=t.hidden?'Voir les photos':'Masquer les photos'});
host.querySelectorAll('[data-copy]').forEach(c=>c.onclick=async()=>{try{await navigator.clipboard.writeText(c.dataset.copy);toast('Copié.')}catch{toast(c.dataset.copy)}})};
document.querySelectorAll('[data-sel-filter]').forEach(b=>b.onclick=()=>{selFilter=b.dataset.selFilter;document.querySelectorAll('[data-sel-filter]').forEach(x=>x.classList.toggle('active',x===b));draw()});
if(selCache)draw();api('/api/admin/selections').then(r=>{selCache=r.selections;draw()}).catch(e=>toast(e.message))}
if(page==='Albums')bindLibrary();
// Photos d'une galerie : ouvre la page « Photos » filtrée ; « Ajouter » ouvre l'import sur cette galerie.
document.querySelectorAll('[data-lib-event]').forEach(b=>b.onclick=()=>{lib.eventId=b.dataset.libEvent;lib.album='';lib.selected.clear();navigate('Albums')});
document.querySelectorAll('[data-upload-to]').forEach(b=>b.onclick=()=>{uploadEventId=b.dataset.uploadTo;navigate('Photos')});
function bindLibrary(){const grid=document.getElementById('lib-grid');const bar=document.getElementById('lib-bar');if(!grid)return bindLibFilters();const list=libList();const ev=d.events.find(e=>e.id===lib.eventId);
// La sélection change sans tout redessiner (la page garde sa position).
const sync=()=>{grid.querySelectorAll('[data-lib-photo]').forEach(c=>{const on=lib.selected.has(c.dataset.libPhoto);c.classList.toggle('is-selected',on);c.querySelector('.lib-pick').setAttribute('aria-pressed',on)});bar.innerHTML=libBar(list,ev);bar.classList.toggle('has-selection',lib.selected.size>0);bindBar()};
grid.querySelectorAll('.lib-pick').forEach(b=>b.onclick=e=>{const id=b.closest('[data-lib-photo]').dataset.libPhoto;const ids=list.map(p=>p.id);const at=ids.indexOf(id);
if(e.shiftKey&&lib.last&&ids.includes(lib.last)){const from=ids.indexOf(lib.last);const on=!lib.selected.has(id);for(const x of ids.slice(Math.min(from,at),Math.max(from,at)+1))on?lib.selected.add(x):lib.selected.delete(x)}else lib.selected.has(id)?lib.selected.delete(id):lib.selected.add(id);lib.last=id;sync()});
const selectedIds=()=>list.filter(p=>lib.selected.has(p.id)).map(p=>p.id);
function bindBar(){bar.querySelector('#lib-all').onchange=e=>{lib.selected=new Set(e.target.checked?list.map(p=>p.id):[]);sync()};
bar.querySelector('#lib-clear')?.addEventListener('click',()=>{lib.selected.clear();sync()});
bar.querySelector('#lib-move')?.addEventListener('click',()=>{const ids=selectedIds();const names=[...new Set(d.photos.map(p=>p.album))];modal(`Album — ${plural(ids.length,'photo','photos')}`,`<label>Nom de l’album<input name="album" required maxlength="80" list="lib-album-names" placeholder="Ex. Cérémonie, Soirée…"><datalist id="lib-album-names">${names.map(n=>`<option value="${escape(n)}">`).join('')}</datalist></label><p class="small">Un nouveau nom crée l’album ; un nom existant y ajoute les photos.</p>`,async v=>{const r=await api('/api/admin/photos/album',{method:'POST',body:{photoIds:ids,album:v.album}});lib.selected.clear();await refresh();toast(`${plural(r.updated,'photo déplacée','photos déplacées')} dans « ${r.album} ».`)},{submit:'Déplacer'})});
bar.querySelector('#lib-delete')?.addEventListener('click',()=>{const ids=selectedIds();const shown=list.filter(p=>lib.selected.has(p.id)).slice(0,6);modal(`Supprimer ${plural(ids.length,'photo','photos')}`,`<div class="lib-confirm-strip">${shown.map(p=>`<img src="${escape(p.thumb||p.preview)}" alt="">`).join('')}${ids.length>shown.length?`<span>+${ids.length-shown.length}</span>`:''}</div><p>Ces photos seront supprimées définitivement, avec leurs favoris, commentaires et sélections. Cette action ne peut pas être annulée.</p>`,async()=>{const r=await api('/api/admin/photos/delete',{method:'POST',body:{photoIds:ids}});lib.selected.clear();await refresh();toast(`${plural(r.deleted,'photo supprimée','photos supprimées')}.`)},{submit:`Supprimer ${plural(ids.length,'photo','photos')}`,danger:true})});
bar.querySelector('#lib-delete-all')?.addEventListener('click',()=>{const n=service.photos(ev.id).length;modal('Vider la galerie',`<p>Supprimer <strong>les ${plural(n,'photo','photos')}</strong> de « ${escape(ev.name)} » ? La galerie reste en place (titre, client, réglages), mais vide.</p><label><span>Je comprends que c’est définitif</span><input type="checkbox" name="ok" required></label>`,async()=>{const r=await api('/api/admin/photos/delete',{method:'POST',body:{eventId:ev.id}});lib.selected.clear();await refresh();toast(`Galerie vidée : ${plural(r.deleted,'photo supprimée','photos supprimées')}.`)},{submit:`Supprimer les ${n} photos`,danger:true})})}
bindBar();bindLibFilters()}
function bindLibFilters(){document.getElementById('lib-event')?.addEventListener('change',e=>{lib.eventId=e.target.value;lib.album='';lib.selected.clear();lib.last=null;render()});document.querySelectorAll('[data-lib-album]').forEach(b=>b.onclick=()=>{lib.album=b.dataset.libAlbum;lib.selected.clear();lib.last=null;render()})}
document.querySelectorAll('[data-up-photo]').forEach(b=>b.onclick=act(async()=>{await api(`/api/admin/photos/${b.dataset.upPhoto}/move-up`,{method:'POST'});await refresh()}));
document.querySelectorAll('[data-cover-photo]').forEach(b=>b.onclick=act(async()=>{const p=d.photos.find(p=>p.id===b.dataset.coverPhoto);await api(`/api/admin/events/${p.eventId}/cover`,{method:'POST',body:{photoId:p.id}});await refresh();toast('Couverture mise à jour.')}));
document.querySelectorAll('[data-remove-photo]').forEach(b=>b.onclick=()=>{const p=d.photos.find(p=>p.id===b.dataset.removePhoto);modal('Supprimer la photo',`<p>Supprimer définitivement <strong>${escape(p?.filename||'cette photo')}</strong> ? Ses favoris et commentaires disparaissent aussi.</p>`,async()=>{await api(`/api/admin/photos/${b.dataset.removePhoto}`,{method:'DELETE'});lib.selected.delete(b.dataset.removePhoto);await refresh();toast('Photo supprimée.')},{submit:'Supprimer',danger:true})});
// ----- Clients -----
const newClient=()=>clientForm();document.getElementById('new-client')?.addEventListener('click',newClient);document.getElementById('new-client-quick')?.addEventListener('click',newClient);
function clientForm(c){modal(c?'Modifier le client':'Nouveau client',`<label>Nom complet<input name="name" required maxlength="120" value="${escape(c?.name||'')}"></label><label>E-mail<input name="email" type="email" required value="${escape(c?.email||'')}"></label><label>Téléphone<input name="phone" maxlength="40" value="${escape(c?.phone||'')}"></label>${c?'':`<label>Mot de passe temporaire<input name="password" type="password" minlength="8" required autocomplete="new-password"></label>${sendBox('Envoyer ses accès par e-mail')}`}`,async v=>{const body={name:v.name,email:v.email,phone:v.phone};if(!c){body.password=v.password;body.sendEmail=!!v.sendEmail}const r=await api(c?`/api/admin/clients/${c.id}`:'/api/admin/clients',{method:c?'PATCH':'POST',body});await refresh();toast(c?'Client enregistré.':withEmail('Client créé.',r.email))})}
document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>window.open(`/client.html?preview=${b.dataset.preview}`,'_blank','noopener'));
document.querySelectorAll('[data-edit-client]').forEach(b=>b.onclick=()=>clientForm(byId(b.dataset.editClient)));
document.querySelectorAll('[data-toggle-client]').forEach(b=>b.onclick=()=>toggleClient(byId(b.dataset.toggleClient)));
const resetForm=(a,url)=>modal(`Nouveau mot de passe — ${a.name}`,`<label>Mot de passe temporaire<input name="password" type="password" minlength="8" required autocomplete="new-password"></label>${sendBox('Envoyer par e-mail')}`,async v=>{const r=await api(url,{method:'POST',body:{password:v.password,sendEmail:!!v.sendEmail}});toast(withEmail('Mot de passe temporaire enregistré.',r.email))});
document.querySelectorAll('[data-reset-client]').forEach(b=>b.onclick=()=>resetForm(byId(b.dataset.resetClient),`/api/admin/clients/${b.dataset.resetClient}/password`));
const openMessage=a=>modal(`Message à ${a.name}`,`<label>Objet<input name="subject" required maxlength="150" value="Un message de ${escape(auth.session()?.senderName||auth.session()?.name||"KentraPix")}"></label><label>Message<textarea name="message" required maxlength="5000"></textarea></label>`,async v=>{const r=await api(`/api/admin/accounts/${a.id}/message`,{method:'POST',body:v});toast(withEmail('Message traité.',r.email))},{submit:'Envoyer'});
document.querySelectorAll('[data-message]').forEach(b=>b.onclick=()=>openMessage(byId(b.dataset.message)));
// Pause : le client ne peut plus se connecter (sessions fermées) ; ses galeries et liens de partage sont gardés.
const toggleClient=act(async c=>{await api(`/api/admin/clients/${c.id}`,{method:'PATCH',body:{active:!c.active}});await refresh();toast(c.active?`${c.name} est en pause : il ne peut plus se connecter.`:`${c.name} peut de nouveau se connecter.`)});
// Ajouter des photos pour un client : une de ses galeries, ou une nouvelle, puis la page d'import.
function addPhotosFor(c){const gals=d.events.filter(e=>e.clientId===c.id);const today=new Date().toISOString().slice(0,10);
modal(`Ajouter des photos — ${c.name}`,`<label>Galerie<select name="eventId" id="ap-event">${gals.map(e=>`<option value="${e.id}">${escape(e.name)} (${service.photos(e.id).length} photo${service.photos(e.id).length>1?'s':''})</option>`).join('')}<option value="__new" ${gals.length?'':'selected'}>＋ Nouvelle galerie…</option></select></label><div id="ap-new" class="ap-new"${gals.length?' hidden':''}><label>Nom de la galerie<input name="name" maxlength="160" placeholder="Ex. Séance famille"></label><label>Type<input name="type" list="ap-types" maxlength="80" value="Séance photo"><datalist id="ap-types">${types.map(t=>`<option>${t}</option>`).join('')}</datalist></label><label>Date<input name="date" type="date" value="${today}"></label></div>`,async v=>{let id=v.eventId;
if(id==='__new'){if(!v.name?.trim())throw Error('Donnez un nom à la nouvelle galerie.');const r=await api('/api/admin/events',{method:'POST',form:toForm({clientId:c.id,name:v.name.trim(),type:v.type||'Séance photo',date:v.date||today})});id=r.event.id;await refresh();toast(`Galerie « ${r.event.name} » créée (brouillon). Déposez les photos.`)}
uploadEventId=id;navigate('Photos')},{submit:'Continuer vers l’import'});
const host=document.getElementById('overlays');host.querySelector('#ap-event').onchange=e=>{host.querySelector('#ap-new').hidden=e.target.value!=='__new'}}
// Supprimer : choix pour les galeries, confirmation obligatoire.
function deleteClient(c){const gals=d.events.filter(e=>e.clientId===c.id);const n=gals.reduce((t,e)=>t+service.photos(e.id).length,0);
modal(`Supprimer ${c.name}`,`<p>Le compte de <strong>${escape(c.name)}</strong> (${escape(c.email)}) sera supprimé : il ne pourra plus se connecter, et ses favoris, sélections, commentaires et liens de partage seront effacés.</p>${gals.length?`<fieldset class="del-choice"><legend>Ses ${gals.length} galerie${gals.length>1?'s':''} (${n} photo${n>1?'s':''})</legend><label><span><strong>Les garder</strong><small>Elles passent sur votre compte, en brouillon.</small></span><input type="radio" name="galleries" value="keep" checked></label><label><span><strong>Les supprimer avec les photos</strong><small>Définitif : les photos sont effacées du stockage.</small></span><input type="radio" name="galleries" value="delete"></label></fieldset>`:'<input type="hidden" name="galleries" value="keep">'}<label><span>Je comprends que la suppression est définitive</span><input type="checkbox" name="ok" required></label>`,async v=>{const r=await api(`/api/admin/clients/${c.id}`,{method:'DELETE',body:{galleries:v.galleries||'keep'}});await refresh();toast(r.count?(r.galleries==='delete'?`${c.name} supprimé, avec ${r.count} galerie(s).`:`${c.name} supprimé. Ses galeries sont gardées en brouillon.`):`${c.name} supprimé.`)},{submit:'Supprimer le client',danger:true})}
// Fenêtre « Gérer » : tout ce qu'on peut faire pour un client, au même endroit.
function manageClient(c){const gals=d.events.filter(e=>e.clientId===c.id);const n=gals.reduce((t,e)=>t+service.photos(e.id).length,0);
const action=(key,ico,label,hint,cls='')=>`<button type="button" class="mc-action ${cls}" data-mc="${key}">${icon(ico)}<span><strong>${label}</strong><small>${hint}</small></span></button>`;
modal(c.name,`<div class="mc-head">${person(c)}${c.active?pill('Actif','is-live'):pill('En pause','is-muted')}</div><div class="mc-stats"><span><b>${gals.length}</b> galerie${gals.length>1?'s':''}</span><span><b>${n}</b> photo${n>1?'s':''}</span><span>${ago(c.lastLoginAt)}</span></div>${gals.length?`<ul class="mc-gals">${gals.map(e=>`<li><span>${escape(e.name)} <small>${service.photos(e.id).length} photo${service.photos(e.id).length>1?'s':''}${e.published?'':' · brouillon'}</small></span><button type="button" class="text-link" data-mc-upload="${e.id}">${icon('upload')} Ajouter</button></li>`).join('')}</ul>`:''}<div class="mc-actions">${action('photos','upload','Ajouter des photos','Dans une de ses galeries ou une nouvelle')}${action('preview','eye','Voir son espace','Comme le client le voit')}${action('message','mail','Envoyer un message','Par e-mail')}${action('edit','edit','Modifier','Nom, e-mail, téléphone')}${action('password','key','Nouveau mot de passe','Temporaire, envoyé par e-mail')}${action('pause',c.active?'pause':'play',c.active?'Mettre en pause':'Réactiver',c.active?'Bloque la connexion, garde tout':'Il pourra de nouveau se connecter')}${action('delete','trash','Supprimer le client','Compte et données','danger')}</div>`);
const host=document.getElementById('overlays');const go=fn=>()=>{host.innerHTML='';fn()};
const run={photos:()=>addPhotosFor(c),preview:()=>window.open(`/client.html?preview=${c.id}`,'_blank','noopener'),message:()=>openMessage(c),edit:()=>clientForm(c),password:()=>resetForm(c,`/api/admin/clients/${c.id}/password`),pause:()=>toggleClient(c),delete:()=>deleteClient(c)};
host.querySelectorAll('[data-mc]').forEach(b=>b.onclick=go(run[b.dataset.mc]));
host.querySelectorAll('[data-mc-upload]').forEach(b=>b.onclick=go(()=>{uploadEventId=b.dataset.mcUpload;navigate('Photos')}))}
document.querySelectorAll('[data-add-photos]').forEach(b=>b.onclick=()=>addPhotosFor(byId(b.dataset.addPhotos)));
document.querySelectorAll('[data-manage-client]').forEach(b=>b.onclick=()=>manageClient(byId(b.dataset.manageClient)));
// ----- Équipe (propriétaire) -----
document.getElementById('new-admin')?.addEventListener('click',()=>modal('Nouvel admin',`<label>Nom complet<input name="name" required maxlength="120"></label><label>E-mail<input name="email" type="email" required></label><label>Mot de passe temporaire<input name="password" type="password" minlength="8" required autocomplete="new-password"></label>${sendBox('Envoyer l’invitation par e-mail')}`,async v=>{const r=await api('/api/admin/team',{method:'POST',body:{name:v.name,email:v.email,password:v.password,sendEmail:!!v.sendEmail}});await refresh();toast(withEmail('Admin ajouté.',r.email))}));
document.getElementById('promote-client')?.addEventListener('click',()=>{if(!d.clients.length)return toast('Aucun client à nommer.');modal('Nommer un client admin',`<label>Client<select name="id">${d.clients.map(c=>`<option value="${c.id}">${escape(c.name)} — ${escape(c.email)}</option>`).join('')}</select></label>${sendBox('Prévenir par e-mail')}<p class="small">Il gardera ses galeries et aura accès au studio.</p>`,async v=>{const r=await api(`/api/admin/team/${v.id}`,{method:'PATCH',body:{role:'admin',sendEmail:!!v.sendEmail}});await refresh();toast(withEmail('Nouvel admin nommé.',r.email))})});
const makeOwner=a=>modal('Nommer propriétaire',`<p><strong>${escape(a.name)}</strong> deviendra propriétaire : il gèrera l’équipe et les réglages, comme vous. Chaque propriétaire ne voit que ses propres clients et galeries.</p>`,async()=>{await api(`/api/admin/team/${a.id}`,{method:'PATCH',body:{role:'owner'}});await refresh();toast('Nouveau propriétaire nommé.')},{submit:'Nommer propriétaire'});
document.getElementById('new-owner')?.addEventListener('click',()=>{const admins=d.team.filter(a=>a.role==='admin'&&a.active);if(!admins.length)return toast('Créez d’abord un admin (Nouvel admin), puis nommez-le propriétaire.');modal('Nouveau propriétaire',`<label>Choisir un admin<select name="id">${admins.map(a=>`<option value="${a.id}">${escape(a.name)} — ${escape(a.email)}</option>`).join('')}</select></label><p class="small">Il aura les mêmes droits que vous sur l’équipe et les réglages. Chaque propriétaire ne voit que ses propres clients et galeries.</p>`,async v=>{await api(`/api/admin/team/${v.id}`,{method:'PATCH',body:{role:'owner'}});await refresh();toast('Nouveau propriétaire nommé.')},{submit:'Nommer propriétaire'})});
document.querySelectorAll('[data-make-owner]').forEach(b=>b.onclick=()=>makeOwner(byId(b.dataset.makeOwner)));
document.querySelectorAll('[data-remove-owner]').forEach(b=>b.onclick=()=>{const a=byId(b.dataset.removeOwner);modal('Retirer propriétaire',`<p><strong>${escape(a.name)}</strong> redeviendra admin : il garde ses clients mais ne gère plus l’équipe ni les réglages.</p>`,async()=>{await api(`/api/admin/team/${a.id}`,{method:'PATCH',body:{role:'admin'}});await refresh();toast('Propriétaire retiré.')},{danger:true,submit:'Retirer'})});
document.querySelectorAll('[data-demote]').forEach(b=>b.onclick=()=>{const a=byId(b.dataset.demote);modal('Retirer des admins',`<p><strong>${escape(a.name)}</strong> redeviendra client : il gardera ses galeries mais n’aura plus accès au studio.</p>`,async()=>{await api(`/api/admin/team/${a.id}`,{method:'PATCH',body:{role:'client'}});await refresh();toast('Accès studio retiré.')})});
document.querySelectorAll('[data-toggle-admin]').forEach(b=>b.onclick=act(async()=>{const a=byId(b.dataset.toggleAdmin);await api(`/api/admin/team/${a.id}`,{method:'PATCH',body:{active:!a.active}});await refresh()}));
document.querySelectorAll('[data-reset-admin]').forEach(b=>b.onclick=()=>resetForm(byId(b.dataset.resetAdmin),`/api/admin/team/${b.dataset.resetAdmin}/password`));
document.querySelectorAll('[data-reset-studio]').forEach(b=>b.onclick=async()=>{if(!confirm('Effacer le mot de passe du studio de ce photographe ? Il en créera un nouveau à sa prochaine ouverture.'))return;try{await api(`/api/admin/team/${b.dataset.resetStudio}/studio-reset`,{method:'POST'});toast('Mot de passe du studio effacé.')}catch(e){toast(e.message)}});
// ----- Commentaires -----
const loadComments=()=>api('/api/admin/comments').then(r=>{commentCache=r.comments;drawComments()}).catch(e=>toast(e.message));
// Affiche la liste filtrée (sans recharger) et relie ses boutons.
const drawComments=()=>{const host=document.getElementById('comment-list');if(!host||!commentCache)return;const all=commentCache;for(const k of['all','client','family','staff']){const el=document.querySelector(`[data-ccount="${k}"]`);if(el)el.textContent=all.filter(c=>commentKind(c,k)).length}host.innerHTML=commentList(all.filter(c=>commentKind(c,commentFilter)));host.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>modal(`Répondre — ${b.dataset.replyName}`,'<label>Réponse du studio<textarea name="body" required maxlength="1000"></textarea></label>',async v=>{await api(`/api/admin/photos/${b.dataset.reply}/comments`,{method:'POST',body:{body:v.body}});toast('Réponse publiée.');loadComments()}));host.querySelectorAll('[data-del-comment]').forEach(b=>b.onclick=()=>modal('Supprimer le commentaire','<p>Supprimer définitivement ce commentaire ?</p>',async()=>{await api(`/api/admin/comments/${b.dataset.delComment}`,{method:'DELETE'});loadComments()},{submit:'Supprimer',danger:true}))};
document.querySelectorAll('[data-cfilter]').forEach(b=>b.onclick=()=>{commentFilter=b.dataset.cfilter;document.querySelectorAll('[data-cfilter]').forEach(x=>x.classList.toggle('active',x===b));drawComments()});
if(page==='Comments')loadComments();
// ----- Notifications du studio -----
let noticePolls=0;
const loadAnnouncements=()=>api('/api/admin/announcements').then(r=>{const host=document.getElementById('announcement-list');if(!host)return;host.innerHTML=`${r.mail.configured?`<p class="small notice-quota">E-mails envoyés aujourd’hui : ${r.mail.sentToday} / ${r.mail.dailyLimit}</p>`:''}${announcementList(r.announcements)}`;
host.querySelectorAll('[data-del-announcement]').forEach(b=>b.onclick=()=>{const a=r.announcements.find(x=>x.id===b.dataset.delAnnouncement);const later=isLater(a);modal(later?'Annuler l’envoi':'Supprimer la notification',`<p>${later?`« ${escape(a.title)} » ne sera pas envoyée.`:`« ${escape(a.title)} » disparaîtra de la cloche de vos clients.${a.emailsSent?' Les e-mails déjà envoyés ne peuvent pas être repris.':''}`}</p>`,async()=>{await api(`/api/admin/announcements/${a.id}`,{method:'DELETE'});toast(later?'Envoi annulé.':'Notification supprimée.');loadAnnouncements()})});
// E-mails en cours d'envoi : la liste se met à jour toute seule (2 minutes au plus).
clearTimeout(window.noticeTimer);if(noticePolls<30&&r.announcements.some(a=>a.sendEmail&&!isLater(a)&&!emailsDone(a))){noticePolls++;window.noticeTimer=setTimeout(()=>document.getElementById('announcement-list')&&loadAnnouncements(),4000)}}).catch(e=>toast(e.message));
if(page==='Announcements'){noticePolls=0;loadAnnouncements()}
document.getElementById('new-announcement')?.addEventListener('click',()=>{const clients=d.clients.filter(c=>c.active);if(!clients.length)return toast('Ajoutez d’abord un client actif.');
const pad=n=>String(n).padStart(2,'0');const local=t=>`${t.getFullYear()}-${pad(t.getMonth()+1)}-${pad(t.getDate())}T${pad(t.getHours())}:${pad(t.getMinutes())}`;const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);tomorrow.setHours(9,0,0,0);
modal('Nouvelle notification',`<label>Titre<input name="title" required maxlength="150" placeholder="Ex. Séances photo de Noël"></label><label>Message<textarea name="body" required maxlength="5000" rows="5"></textarea></label><label>Pour<select name="audience" id="ann-audience"><option value="all">Tous mes clients actifs (${clients.length})</option><option value="some">Choisir des clients…</option></select></label><fieldset class="ann-clients" id="ann-clients" hidden><legend>Clients</legend>${clients.map(c=>`<label><span>${escape(c.name)} <small>${escape(c.email)}</small></span><input type="checkbox" name="clientIds" value="${c.id}"></label>`).join('')}</fieldset><label>Galerie liée <span class="optional">(facultatif — s’ouvre quand le client touche la notification)</span><select name="eventId"><option value="">Aucune</option>${d.events.filter(e=>e.published&&!e.archived).map(e=>`<option value="${e.id}">${escape(e.name)} — ${escape(ownerOf(e)?.name||'')}</option>`).join('')}</select></label><label><span>Envoyer aussi par e-mail${d.mail.configured?'':' <small>(Resend non configuré)</small>'}</span><input type="checkbox" name="sendEmail" ${d.mail.configured?'checked':''}></label><label>Quand<select name="when" id="ann-when"><option value="now">Tout de suite</option><option value="later">Programmer…</option></select></label><label id="ann-at" hidden>Date et heure d’envoi<input type="datetime-local" name="sendAt" min="${local(new Date())}" value="${local(tomorrow)}"></label>`,async v=>{
const clientIds=[...document.querySelectorAll('#overlays [name="clientIds"]:checked')].map(i=>i.value);
if(v.audience==='some'&&!clientIds.length)throw Error('Choisissez au moins un client.');
let sendAt=null;if(v.when==='later'){if(!v.sendAt)throw Error('Choisissez la date et l’heure d’envoi.');sendAt=new Date(v.sendAt).toISOString()}
const r=await api('/api/admin/announcements',{method:'POST',body:{title:v.title,body:v.body,audience:v.audience,clientIds,eventId:v.eventId||null,sendEmail:!!v.sendEmail,sendAt}});
toast(r.scheduled?`Notification programmée pour ${r.recipients} client(s) : le ${when(sendAt)}.`:`Notification publiée pour ${r.recipients} client(s).${v.sendEmail?(r.mail?' Les e-mails partent…':' (e-mails non envoyés : Resend non configuré)'):''}`);noticePolls=0;loadAnnouncements()});
const host=document.getElementById('overlays');host.querySelector('#ann-audience').onchange=e=>{host.querySelector('#ann-clients').hidden=e.target.value!=='some'};host.querySelector('#ann-when').onchange=e=>{host.querySelector('#ann-at').hidden=e.target.value!=='later'}});
// ----- E-mails -----
const loadLog=()=>api('/api/admin/emails').then(r=>{const host=document.getElementById('email-log');if(host)host.innerHTML=emailTable(r.emails)}).catch(e=>toast(e.message));
if(page==='Emails'){loadLog();const kind=document.getElementById('test-kind'),frame=document.getElementById('test-preview');
// Aperçu du modèle choisi (données d'exemple), puis envoi réel via Resend.
const show=act(async()=>{const r=await api(`/api/admin/emails/preview/${kind.value}`);document.getElementById('test-subject').textContent=`Objet : ${r.subject}`;frame.srcdoc=r.html});kind.onchange=show;show();
document.getElementById('send-test').onclick=act(async()=>{const b=document.getElementById('send-test');b.disabled=true;try{const r=await api('/api/admin/emails/test',{method:'POST',body:{kind:kind.value,to:document.getElementById('test-to').value}});toast(withEmail('Test traité.',r.email));await loadLog()}finally{b.disabled=false}})}
// ----- Événements -----
const ownerOptions=sel=>`${d.clients.length?`<optgroup label="Clients">${d.clients.map(c=>`<option value="${c.id}" ${c.id===sel?'selected':''}>${escape(c.name)}</option>`).join('')}</optgroup>`:''}<optgroup label="Équipe">${d.team.map(a=>`<option value="${a.id}" ${a.id===sel?'selected':''}>${escape(a.name)} (${roleLabel[a.role]})</option>`).join('')}</optgroup>`;
document.getElementById('new-event')?.addEventListener('click',()=>modal('Nouvel événement',`<label>Pour<select name="clientId">${ownerOptions()}</select></label><label>Nom<input name="name" required maxlength="160"></label><label>Type<input name="type" list="event-types" required maxlength="80"><datalist id="event-types">${types.map(t=>`<option>${t}</option>`).join('')}</datalist></label><label>Date<input name="date" type="date" required></label><label>Lieu<input name="location" maxlength="160"></label><label>Description<textarea name="description"></textarea></label><label>Photo de couverture<input type="file" name="coverFile" accept="image/*"></label>`,async values=>{const r=await api('/api/admin/events',{method:'POST',form:toForm(values)});uploadEventId=r.event.id;await service.load('admin');navigate('Photos');toast('Événement créé. Importez vos photos.')}));
document.querySelectorAll('[data-view-selection]').forEach(b=>b.onclick=act(async()=>{const e=d.events.find(e=>e.id===b.dataset.viewSelection);const r=await api(`/api/admin/events/${e.id}/selection`);modal(`Sélection — ${e.name}`,r.selections.length?r.selections.map(x=>`<section class="sel-block"><div class="row between"><strong>${escape(x.name)}</strong><span class="small">${x.submittedAt?`Envoyée le ${new Date(x.submittedAt).toLocaleString('fr-FR')}`:'Pas encore envoyée'}</span></div>${x.photos.length?`<p class="pick-list">N° ${x.photos.map(p=>p.number).join(', ')}</p><button type="button" class="btn sm" data-copy="${x.photos.map(p=>p.number).join(', ')}">Copier les numéros</button><div class="sel-thumbs">${x.photos.map(p=>`<figure><img src="${escape(p.preview)}" alt="" loading="lazy"><figcaption>N° ${p.number}</figcaption></figure>`).join('')}</div>`:'<p class="small">Aucune photo choisie.</p>'}${x.note?`<blockquote>${escape(x.note).replace(/\n/g,'<br>')}</blockquote>`:''}</section>`).join(''):'<p>Aucune sélection pour le moment.</p>');document.querySelectorAll('[data-copy]').forEach(c=>c.onclick=async()=>{try{await navigator.clipboard.writeText(c.dataset.copy);toast('Numéros copiés.')}catch{toast(c.dataset.copy)}})}));
// Partage famille : le studio gère les liens de la galerie (ceux du client compris).
document.querySelectorAll('[data-share-event]').forEach(b=>b.onclick=()=>{const e=d.events.find(x=>x.id===b.dataset.shareEvent);openShareManager({event:e,base:'/api/admin',canDl:!!d.permissions.share_download&&e.allowDownload&&!e.selectionMode,studio:true,owner:isOwner(),modal,toast})});
document.querySelectorAll('[data-notify]').forEach(b=>b.onclick=act(async()=>{const r=await api(`/api/admin/events/${b.dataset.notify}/notify`,{method:'POST'});toast(withEmail('Notification traitée.',r.email))}));
document.querySelectorAll('[data-manage-event]').forEach(b=>b.onclick=()=>{const e=d.events.find(e=>e.id===b.dataset.manageEvent);modal(e.name,`<label>Titre<input name="name" required maxlength="160" value="${escape(e.name)}"></label><label>Pour<select name="clientId">${ownerOptions(e.clientId)}</select></label><label><span>Publié</span><input name="published" type="checkbox" ${e.published?'checked':''}></label>${e.published&&!e.archived?'':'<label><span>Prévenir par e-mail à la publication</span><input name="notify" type="checkbox" checked></label>'}<label><span>Téléchargements autorisés</span><input name="download" type="checkbox" ${e.allowDownload?'checked':''}></label><label><span>Mode sélection <small>(le client choisit des numéros, aucun téléchargement)</small></span><input name="selectionMode" type="checkbox" ${e.selectionMode?'checked':''}></label><label>Nombre maximum de photos à choisir <span class="optional">(facultatif)</span><input name="selectionLimit" type="number" min="1" step="1" value="${e.selectionLimit??''}"></label><label>Photos débloquées pour le client <span class="optional">(facultatif)</span><input name="unlockLimit" type="number" min="0" step="1" value="${e.unlockLimit??''}" placeholder="Toutes"><small class="field-hint">Ex. 10 : le client ne voit que les photos 1 à 10. Augmentez le nombre pour en débloquer d’autres (10, 20, 30…). Vide = toutes.</small></label><label>Photos non débloquées<select name="lockMode"><option value="locked"${e.lockMode!=='hidden'?' selected':''}>Visibles mais verrouillées</option><option value="hidden"${e.lockMode==='hidden'?' selected':''}>Cachées</option></select></label><label>Message pour le client <span class="optional">(facultatif)</span><input name="lockReason" maxlength="300" value="${escape(e.lockReason||'')}" placeholder="Ex. Disponibles après le paiement du solde"><small class="field-hint">Affiché au client pour expliquer pourquoi il ne peut pas ouvrir les autres photos.</small></label><label>Disponible jusqu’au <span class="optional">(facultatif — rappel automatique au client 7 jours avant)</span><input name="expiresAt" type="date" value="${e.expiresAt||''}"></label><label>Changer la couverture<input type="file" name="coverFile" accept="image/*"></label><label>Musique du diaporama <span class="optional">${e.music?'(une musique est déjà en place)':'(MP3, M4A… 20 Mo max)'}</span><input type="file" name="musicFile" accept="audio/*"></label>${e.music?'<label><span>Retirer la musique</span><input type="checkbox" name="removeMusic"></label>':''}<label><span>Archivé</span><input type="checkbox" name="archived" ${e.archived?'checked':''}></label><label><span>Supprimer l’événement et ses photos</span><input type="checkbox" name="delete"></label>`,async values=>{if(values.delete){if(!confirm(`Supprimer « ${e.name} » et toutes ses photos ? Cette action est définitive.`))return;await api(`/api/admin/events/${e.id}`,{method:'DELETE'});return refresh()}const form=toForm({name:values.name,clientId:values.clientId,published:values.published?'1':'0',download:values.download?'1':'0',archived:values.archived?'1':'0',notify:values.notify?'1':'0',selectionMode:values.selectionMode?'1':'0',selectionLimit:values.selectionLimit||'',unlockLimit:values.unlockLimit??'',lockMode:values.lockMode||'locked',lockReason:values.lockReason||'',expiresAt:values.expiresAt||'',coverFile:values.coverFile});const r=await api(`/api/admin/events/${e.id}`,{method:'PATCH',form});if(values.musicFile?.size)await api(`/api/admin/events/${e.id}/music`,{method:'POST',form:toForm({music:values.musicFile})});else if(values.removeMusic)await api(`/api/admin/events/${e.id}/music`,{method:'DELETE'});await refresh();toast(withEmail('Galerie enregistrée.',r.email))})});
document.querySelectorAll('[data-permission]').forEach(i=>i.onchange=act(async()=>{try{d.permissions=(await api('/api/admin/permissions',{method:'PUT',body:{[i.dataset.permission]:i.checked}})).permissions}catch(e){i.checked=!i.checked;throw e}}));
if(page==='Photos')bindUploader(toast)}
